function CatHouseMatchPopupInviteGroup:FreshUI(matchStatus, matchType, otherConsumePrice, deliveryData)
    --- 选择猫状态
    --local isSelectCat = matchStatus == MatchStatus.SelectCat
    --self.BtnInviteImg.Status = isSelectCat and 1 or 2
    --- 邀请中
    local isInviting = matchStatus == MatchStatus.Inviting
    KTool.SetActive(self.InviteGroup.gameObject, not isInviting)
    KTool.SetActive(self.CancelInvitation.gameObject, isInviting)
    if not isInviting then
        --- 孵化消耗道具id
        local goodsId = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.HatchConsumeId).num)
        --- 孵化消耗道具数量
        local num     = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.HatchConsumeNum).num)

        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
        self.ImgConsume:LoadSprite(goodsVo.photoPath)
        self.ConsumeTxtNum.text = string.format("x%d", num)
    else
        self:FreshTextTime(deliveryData)
    end

    --- 集会配对
    local isRallyMatch = matchType == MatchType.RallyMatch
    KTool.SetActive(self.CommonBtnConsumePop.gameObject, isRallyMatch)
    if isRallyMatch then
        local goodsId = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.RallyGoodsId).num)
        -- local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
        -- CfUtils.FillImage(self.OtherConsumeImgIcon, goodsVo.photoPath)
        -- self.OtherConsumeTextNumber.text = checkNumber(otherConsumePrice)

        CfUtils.FillCommonBtnConsumePopNode(self.CommonBtnConsumePop.gameObject, goodsId, checkNumber(otherConsumePrice))
    end


end

function CatHouseMatchPopupInviteGroup:SetButtonStatus(myCat, otherCat)
    local fontStyleButton = KTool.GetComponent(self.BtnInvite.gameObject, typeof(CS.Game.Native.Common.FontStyleButton))
    if isNull(myCat) or isNull(otherCat) then
        fontStyleButton:ResetFontStyle("B17", localize("开始配对"))
    else
        fontStyleButton:ResetFontStyle("B1", localize("开始配对"))
    end
end

function CatHouseMatchPopupInviteGroup:FreshTextTime(deliveryData)
    self.TextTime.text = GetTimeHMS2(deliveryData.remainTime)
end

